import{_ as t,o,c as p,a5 as l}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"自定义 Mybatis 框架","description":"","frontmatter":{"title":"自定义 Mybatis 框架","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/自定义 Mybatis 框架.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/自定义 Mybatis 框架.md"}'),r={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/自定义 Mybatis 框架.md"};function i(c,e,a,n,s,d){return o(),p("div",null,[...e[0]||(e[0]=[l('<div><p><strong>知识点：</strong></p><ul><li>（<code>Factory</code> 工厂模式）</li><li>构造者模式（<code>Builder</code> 模式）</li><li>代理模式</li><li>反射</li><li>自定义注解</li><li>注解的反射</li><li>xml 解析数据库元数据</li><li>元数据的反射等。 <strong>分析流程</strong></li></ul><p><strong>前期准备</strong></p><p><strong>创建</strong> <code>Maven</code> <strong>工程</strong> 创建</p><p><code>mybatis02</code></p><p>的工程，工程信息如下：</p><ul><li>Groupid:com.itheima</li><li>ArtifactId:mybatis02</li><li>Packing:jar</li></ul><p><strong>引入相关坐标</strong></p><ul><li>&lt;dependencies&gt;</li><li>&lt;!--</li></ul><p>日志坐标</p><ul><li>--&gt;</li><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;log4j&lt;/groupId&gt;</li><li>&lt;artifactId&gt;log4j&lt;/artifactId&gt;</li><li>&lt;version&gt;1.2.12&lt;/version&gt;</li><li>&lt;/dependency&gt;</li><li>&lt;!--</li></ul><p>解析 <code>xml</code> 的</p><ul><li>dom4j --&gt;</li><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;dom4j&lt;/groupId&gt;</li><li>&lt;artifactId&gt;dom4j&lt;/artifactId&gt;</li><li>&lt;version&gt;1.6.1&lt;/version&gt;</li><li>&lt;/dependency&gt;</li><li>&lt;!-- mysql</li></ul><p>驱动</p><ul><li>--&gt;</li><li>&lt;dependency&gt;</li><li>&lt;groupId&gt;mysql&lt;/groupId&gt;</li><li>&lt;artifactId&gt;mysql-connector-java&lt;/artifactId&gt;</li><li>&lt;version&gt;5.1.6&lt;/version&gt;</li><li>&lt;/dependency&gt;</li><li>&lt;!-- dom4j</li></ul><p>的依赖包</p><p>jaxen --&gt; &lt;dependency&gt; &lt;groupId&gt;jaxen&lt;/groupId&gt; &lt;artifactId&gt;jaxen&lt;/artifactId&gt; &lt;version&gt;1.1.6&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;junit&lt;/groupId&gt; &lt;artifactId&gt;junit&lt;/artifactId&gt; &lt;version&gt;4.10&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt; <strong>引入工具类到项目中</strong></p><p>/** * 用于解析配置文件</p><p><em>/ public class XMLConfigBuilder { /</em>* * 解析主配置文件，把里面的内容填充到 <code>DefaultSqlSession</code> 所需要的地方</p><p><code>*</code></p><p>使用的技术：</p><p>dom4j+xpath</p><ul><li>@param session */ public static void loadConfiguration(DefaultSqlSession session,InputStream config){ try{ // 定义封装连接信息的配置对象（<code>mybatis</code> 的配置对象）</li></ul><p>Configuration cfg = new Configuration(); //1. 获取 <code>SAXReader</code> 对象</p><p>SAXReader reader = new SAXReader(); //2. 根据字节输入流获取 <code>Document</code> 对象</p><p>Document document = reader.read(config); ￼</p><p>Element root = document.getRootElement(); //4. 使用 <code>xpath</code> 中选择指定节点的方式，获取所有 <code>property</code> 节点</p><p>List&lt;Element&gt; propertyElements = root.selectNodes(&quot;//property&quot;); //5. 遍历节点</p><p>for(Element propertyElement : propertyElements){ // 判断节点是连接数据库的哪部分信息</p><p>// 取出 <code>name</code> 属性的值</p><p>String name = propertyElement.attributeValue(&quot;name&quot;); if(&quot;driver&quot;.equals(name)){ // 表示驱动</p><p>// 获取 <code>property</code> 标签 <code>value</code> 属性的值</p><p>String driver = propertyElement.attributeValue(&quot;value&quot;); cfg.setDriver(driver); } if(&quot;url&quot;.equals(name)){ // 表示连接字符串</p><p>// 获取 <code>property</code> 标签 <code>value</code> 属性的值</p><p>String url = propertyElement.attributeValue(&quot;value&quot;); cfg.setUrl(url); } if(&quot;username&quot;.equals(name)){ // 表示用户名</p><p>// 获取 <code>property</code> 标签 <code>value</code> 属性的值</p><p>String username = propertyElement.attributeValue(&quot;value&quot;); cfg.setUsername(username); } if(&quot;password&quot;.equals(name)){ // 表示密码</p><p>// 获取 <code>property</code> 标签 <code>value</code> 属性的值</p><p>String password = propertyElement.attributeValue(&quot;value&quot;); cfg.setPassword(password); } } // 取出 <code>mappers</code> 中的所有 <code>mapper</code> 标签，判断他们使用了 <code>resource</code> 还是 <code>class</code> 属性</p><p>List&lt;Element&gt; mapperElements = root.selectNodes(&quot;//mappers/mapper&quot;); // 遍历集合</p><p>for(Element mapperElement : mapperElements){ // 判断 <code>mapperElement</code> 使用的是哪个属性</p><p>Attribute attribute = mapperElement.attribute(&quot;resource&quot;); if(attribute != null){ System.out.println(&quot; 使用的是</p><p>XML&quot;); // 表示有 <code>resource</code> 属性，用的是</p><p>XML // 取出属性的值</p><p>String mapperPath = attribute.getValue();// 获 取 属 性 的 值</p><p>&quot;com/itheima/dao/IUserDao.xml&quot; // 把映射配置文件的内容获取出来，封装成一个</p><p>map Map&lt;String,Mapper&gt; mappers = loadMapperConfiguration(mapperPath); // 给 <code>configuration</code> 中的 <code>mappers</code> 赋值</p><p>cfg.setMappers(mappers); }else{ System.out.println(&quot; 使用的是注解</p><p>&quot;); // 表示没有 <code>resource</code> 属性，用的是注解</p><p>// 获取 <code>class</code> 属性的值</p><p>String daoClassPath = mapperElement.attributeValue(&quot;class&quot;); // 根据 <code>daoClassPath</code> 获取封装的必要信息</p><p>Map&lt;String,Mapper&gt; mappers = loadMapperAnnotation(daoClassPath); // 给 <code>configuration</code> 中的 <code>mappers</code> 赋值</p><p>cfg.setMappers(mappers); } } // 把配置对象传递给</p><p>DefaultSqlSession session.setCfg(cfg); }catch(Exception e){ throw new RuntimeException(e); }finally{ try { config.close(); }catch(Exception e){ e.printStackTrace(); } } }</p><p>}</p><p>/** * 负责执行 <code>SQL</code> 语句，并且封装结果集</p><p>*/ public class Executor { public &lt;E&gt; List&lt;E&gt; selectList(Mapper mapper, Connection conn) { PreparedStatement pstm = null; ResultSet rs = null; try { //1. 取出 <code>mapper</code> 中的数据</p><p>String queryString = mapper.getQueryString();//select * from user String resultType = mapper.getResultType();<a href="//com.itheima.domain.User" target="_blank" rel="noreferrer">//com.itheima.domain.User</a> Class domainClass = Class.forName(resultType);<a href="//User.class" target="_blank" rel="noreferrer">//User.class</a> //2. 获取 <code>PreparedStatement</code> 对象</p><p>pstm = conn.prepareStatement(queryString); //3. 执行 <code>SQL</code> 语句，获取结果集</p><p>rs = pstm.executeQuery(); //4. 封装结果集</p><p>List&lt;E&gt; list = new ArrayList&lt;E&gt;();// 定义返回值</p><p>while(rs.next()) { // 实例化要封装的实体类对象</p><p>E obj = (E)domainClass.newInstance();//User 对象</p><p>// 取出结果集的元信息：</p><p>ResultSetMetaData ResultSetMetaData rsmd = rs.getMetaData(); // 取出总列数</p><p>int columnCount = rsmd.getColumnCount(); // 遍历总列数</p><p>for (int i = 1; i &lt;= columnCount; i++) { // 获取每列的名称，列名的序号是从 <code>1</code> 开始的</p><p>String columnName = rsmd.getColumnName(i); // 根据得到列名，获取每列的值</p><p>Object columnValue = rs.getObject(columnName); // 给 <code>obj</code> 赋值：使用 <code>Java</code> 内省机制（借助 <code>PropertyDescriptor</code> 实现属性的封装）</p><p>PropertyDescriptor pd = new PropertyDescriptor(columnName,domainClass);// 要求：实体类的属性和数据库表的列名保持一种</p><p>// 获取它的写入方法</p><p>Method writeMethod = pd.getWriteMethod();//setUsername(String username); // 把获取的列的值，给对象赋值</p><p>writeMethod.invoke(obj,columnValue); } // 把赋好值的对象加入到集合中</p><p>list.add(obj); } return list; } catch (Exception e) { throw new RuntimeException(e); } finally { release(pstm,rs); } }</p><p>private void release(PreparedStatement pstm,ResultSet rs){ if(rs != null){ try { rs.close(); }catch(Exception e){ e.printStackTrace(); } } if(pstm != null){ try { pstm.close(); }catch(Exception e){ e.printStackTrace(); } } } }</p><p>/** * 用于创建数据源的工具类</p><p>&lt;/p&gt; <em>/ public class DataSourceUtil { /</em>* * 获取连接</p><ul><li>@param cfg</li><li>@return */ public static Connection getConnection(Configuration cfg) { try { Class.forName(cfg.getDriver()); Connection conn = DriverManager.getConnection(cfg.getUrl(),cfg.getUsername() , cfg.getPassword()); return conn; } catch (Exception e) { throw new RuntimeException(e); } } } <strong>编写</strong></li></ul><ul><li>SqlMapConfig.xml</li><li>&lt;?xmlversion=&quot;1.0&quot;encoding=&quot;UTF-8&quot;?&gt;</li><li>&lt;!--mybatis</li></ul><p>==的主配置文件==</p><ul><li>--&gt;</li><li>&lt;configuration&gt;</li><li>&lt;!--</li></ul><p>==配置环境==</p><ul><li>--&gt;</li><li>&lt;environmentsdefault=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>==配置==<code>mysql</code>==的环境==</p><ul><li>--&gt;</li><li>&lt;environmentid=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>==配置事务的类型==</p><p>--&gt; &lt;transactionManagertype=&quot;JDBC&quot;&gt;&lt;/transactionManager&gt; &lt;!-- ==配置数据源（连接池）==</p><ul><li>--&gt;</li><li>&lt;dataSourcetype=&quot;POOLED&quot;&gt;</li><li>&lt;!--</li></ul><p>==配置连接数据库的==<code>4</code>==个基本信息==</p><p>--&gt; &lt;propertyname=&quot;driver&quot;value=&quot;com.mysql.jdbc.Driver&quot;/&gt; &lt;propertyname=&quot;url&quot;value=&quot;jdbc:mysql://localhost:3306/eesy_mybatis&quot;/&gt; &lt;propertyname=&quot;username&quot;value=&quot;root&quot;/&gt; &lt;propertyname=&quot;password&quot;value=&quot;1234&quot;/&gt; &lt;/dataSource&gt; &lt;/environment&gt; &lt;/environments&gt; &lt;!-- ==指定映射配置文件的位置，映射配置文件指的是每个==<code>dao</code>==独立的配置文件==</p><p>--&gt; &lt;mappers&gt; &lt;!--&lt;mapperresource=&quot;com/itheima/dao/IUserDao.xml&quot;/&gt;--&gt; &lt;mapperclass=&quot;com.itheima.dao.IUserDao&quot;/&gt; &lt;/mappers&gt; &lt;/configuration&gt; <strong>注意：</strong> 此处我们直接使用的是 <code>mybatis</code> 的配置文件，但是由于我们没有使用 <code>mybatis</code> 的 <code>jar</code> 包，所以要把配置文件的约束删掉否则会报错（如果电脑能接入互联网，不删也行）￼ 编写读取配置文件类</p><p>/** * <em>使用类加载器读取配置文件的类</em></p><ul><li>*/</li><li>public</li></ul><p><code>class</code> <code>Resources</code></p><p>{ /** * <em>根据传入的参数，获取一个字节输入流</em></p><p>*@param</p><p>filePath *@return */ public</p><p><code>static</code> <code>InputStream</code> <code>getResourceAsStream(String</code></p><p>filePath){ return</p><p>Resources.class.getClassLoader().getResourceAsStream(filePath); } } <strong>编写</strong> <code>Mapper</code> <strong>类</strong></p><p>/** * <em>用于封装执行的</em><code>SQL</code><em>语句和结果类型的全限定类名</em></p><ul><li>*/</li><li>public</li></ul><p><code>class</code> <code>Mapper{</code></p><p><code>private</code> <code>String</code></p><p>queryString;//SQL private</p><p><code>String</code></p><p>resultType;// <em>实体类的全限定类名</em></p><p><code>public</code> <code>String</code></p><p>getQueryString(){ return</p><p>queryString; }</p><p><code>public</code> <code>void</code></p><p>setQueryString(StringqueryString){ this.queryString=queryString; }</p><p><code>public</code> <code>String</code></p><p>getResultType(){ return</p><p>resultType; }</p><p><code>public</code> <code>void</code></p><p>setResultType(StringresultType){ this.resultType=resultType; } } <strong>编写</strong> <code>Configuration</code> <strong>配置类</strong></p><p>/** * <em>自定义</em><code>mybatis</code><em>的配置类</em></p><ul><li>*/</li><li>public</li></ul><p><code>class</code> <code>Configuration</code></p><p>{ private</p><p><code>String</code></p><p>driver; private</p><p><code>String</code></p><p>url; private</p><p><code>String</code></p><p>username; private</p><p><code>String</code></p><p>password;</p><p><code>private</code> <code>Map\\&lt;String,Mapper\\&gt;</code></p><p><code>mappers=new</code></p><p><code>HashMap\\&lt;String,Mapper\\&gt;();</code></p><p><code>public</code> <code>Map\\&lt;String,Mapper\\&gt;</code></p><p>getMappers(){ return</p><p>mappers; }</p><p><code>public</code> <code>void</code></p><p>setMappers(Map&lt;String,Mapper&gt;mappers){ this.mappers.putAll(mappers);// <em>此处需要使用追加的方式</em><code>}</code></p><p><code>public</code> <code>String</code></p><p>getDriver(){ return</p><p>driver; }</p><p><code>public</code> <code>void</code> <code>setDriver(String</code></p><p>driver){ this.driver=driver; }</p><p><code>public</code> <code>String</code></p><p>getUrl(){ return</p><p>url; }</p><p><code>public</code> <code>void</code> <code>setUrl(String</code></p><p>url){ this.url=url; }</p><p><code>public</code> <code>String</code></p><p>getUsername(){ returnusername; }</p><p><code>public</code> <code>void</code> <code>setUsername(String</code></p><p>username){ this.username=username; }</p><p><code>public</code> <code>String</code></p><p>getPassword(){ return</p><p>password; }</p><p><code>public</code> <code>void</code> <code>setPassword(String</code></p><p>password){ this.password=password; } } <strong>编写</strong> <code>User</code> <strong>实体类</strong><code>User</code> 实体类：</p><p><code>public</code></p><p><code>class</code> <code>User</code> <code>implements</code> <code>Serializable{</code></p><p><code>private</code> <code>Integer</code></p><p>id; private</p><p><code>String</code></p><p>username; private</p><p><code>Date</code></p><p>birthday; private</p><p><code>String</code></p><p>sex; private</p><p><code>String</code></p><p>address;</p><p><code>public</code> <code>Integer</code></p><p>getId(){ return</p><p>id; }</p><p><code>public</code> <code>void</code></p><p>setId(Integerid){ this.id=id; }</p><p>publicStringgetUsername(){ return</p><p>username; }</p><p><code>public</code> <code>void</code></p><p>setUsername(Stringusername){ this.username=username; }</p><p><code>public</code> <code>Date</code></p><p>getBirthday(){ return</p><p>birthday; }</p><p><code>public</code> <code>void</code></p><p>setBirthday(Datebirthday){ this.birthday=birthday; }</p><p><code>public</code> <code>String</code></p><p>getSex(){ return</p><p>sex; }</p><p><code>public</code> <code>void</code></p><p>setSex(Stringsex){ this.sex=sex; }</p><p><code>public</code> <code>String</code></p><p>getAddress(){ return</p><p>address; }</p><p><code>public</code> <code>void</code></p><p>setAddress(Stringaddress){ this.address=address; }</p><p>@Override publicStringtoString(){ return</p><p>&quot;User{&quot;+ &quot;id=&quot;+id+ &quot;,username=&#39;&quot;+username+&#39;&#39;&#39;+ &quot;,birthday=&quot;+birthday+ &quot;,sex=&#39;&quot;+sex+&#39;&#39;&#39;+ &quot;,address=&#39;&quot;+address+&#39;&#39;&#39;+ &#39;}&#39;; } } <strong>基于</strong> <code>XML</code> <strong>的自定义</strong> <code>mybatis</code> <strong>框架</strong><strong>编写持久层接口和</strong></p><p>IUserDao.xml /** *</p><ul><li>&lt;p&gt;Description: 用户的持久层操作</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public interface IUserDao { /</em>*</li><li></li></ul><p>查询所有用户</p><ul><li>@return */ List&lt;User&gt; findAll(); } &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;mapper namespace=&quot;com.itheima.dao.IUserDao&quot;&gt; &lt;!-- 配置查询所有操作</li></ul><p>--&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select * from user &lt;/select&gt; &lt;/mapper&gt; <strong>注意：</strong> 此处我们使用的也是</p><p><code>mybatis</code></p><p>的配置文件，所以也要把约束删除了</p><p><strong>编写构建者类</strong></p><p>/** *</p><ul><li>&lt;p&gt;Title: SqlSessionFactoryBuilder&lt;/p&gt;</li><li>&lt;p&gt;Description: 用于构建 <code>SqlSessionFactory</code> 的</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public class SqlSessionFactoryBuilder { /</em>*</li><li></li></ul><p>根据传入的流，实现对 <code>SqlSessionFactory</code> 的创建</p><ul><li><p>@param in 它就是 <code>SqlMapConfig.xml</code> 的配置以及里面包含的 <code>IUserDao.xml</code> 的配置</p></li><li><p>@return */ public SqlSessionFactory build(InputStream in) { DefaultSqlSessionFactory factory = new DefaultSqlSessionFactory(); // 给 <code>factory</code> 中 <code>config</code> 赋值</p></li></ul><p>factory.setConfig(in); return factory; } } 编写 <code>SqlSessionFactory</code> 接口和实现类</p><p>/** *</p><ul><li>&lt;p&gt;Title: SqlSessionFactory&lt;/p&gt;</li><li>&lt;p&gt;Description: SqlSessionFactory 的接口</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public interface SqlSessionFactory { /</em>*</li><li></li></ul><p>创建一个新的 <code>SqlSession</code> 对象</p><ul><li>@return <em>/ SqlSession openSession(); } /</em>*</li><li></li><li>&lt;p&gt;Title: DefaultSqlSessionFactory&lt;/p&gt;</li><li>&lt;p&gt;Description:SqlSessionFactory 的默认实现</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class DefaultSqlSessionFactory implements SqlSessionFactory { private InputStream config = null; public void setConfig(InputStream config) { this.config = config; } @Override public SqlSession openSession() { DefaultSqlSession session = new DefaultSqlSession(); // 调用工具类解析 <code>xml</code> 文件</li></ul><p>XMLConfigBuilder.loadConfiguration(session, config); return session; } } 编写 SqlSession 接口和实现类</p><p>/** *</p><ul><li>&lt;p&gt;Title: SqlSession&lt;/p&gt;</li><li>&lt;p&gt;Description: 操作数据库的核心对象</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public interface SqlSession { /</em>*</li><li></li></ul><p>创建 <code>Dao</code> 接口的代理对象</p><ul><li>@param daoClass</li><li>@return <em>/ &lt;T&gt; T getMapper(Class&lt;T&gt; daoClass); /</em>*</li><li></li></ul><p>释放资源</p><p><em>/ void close(); } /</em>* *</p><ul><li>&lt;p&gt;Title: DefaultSqlSession&lt;/p&gt;</li><li>&lt;p&gt;Description: SqlSession 的具体实现</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class DefaultSqlSession implements SqlSession { // 核心配置对象</li></ul><p>private Configuration cfg; public void setCfg(Configuration cfg) { this.cfg = cfg; } // 连接对象</p><p>private Connection conn; // 调用 <code>DataSourceUtils</code> 工具类获取连接</p><p>public Connection getConn() { ￼</p><p>conn = DataSourceUtil.getDataSource(cfg).getConnection(); return conn; } catch (Exception e) { throw new RuntimeException(e); } } /** * 动态代理：</p><p><code>*</code></p><p>涉及的类：</p><ul><li>Proxy</li><li><ul><li></li></ul></li></ul><p>使用的方法：</p><ul><li>newProxyInstance</li><li><ul><li></li></ul></li></ul><p>方法的参数：</p><p><code>* ClassLoader</code></p><p>：和被代理对象使用相同的类加载器<code>,</code>通常都是固定的</p><p><code>* Class[]</code></p><p>：代理对象和被代理对象要求有相同的行为。（具有相同的方法）</p><p><code>* InvocationHandler</code></p><p>：如何代理。需要我们自己提供的增强部分的代码</p><p>*/ @Override public &lt;T&gt; T getMapper(Class&lt;T&gt; daoClass) { conn = getConn(); System.out.println(conn); T daoProxy = (T) Proxy.newProxyInstance(daoClass.getClassLoader(),new Class[] {daoClass}, new MapperProxyFactory(cfg.getMappers(),conn)); return daoProxy; } // 释放资源</p><p>@Override public void close() { try { System.out.println(conn); conn.close(); } catch (SQLException e) { e.printStackTrace(); } } // 查询所有方法</p><p>public &lt;E&gt; List&lt;E&gt; selectList(String statement){ Mapper mapper = cfg.getMappers().get(statement); return new Executor().selectList(mapper,conn); } } ￼</p><p>/** *</p><ul><li>&lt;p&gt;Title: MapperProxyFactory&lt;/p&gt;</li><li>&lt;p&gt;Description: 用于创建代理对象是增强方法</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public class MapperProxyFactory implements InvocationHandler { private Map&lt;String,Mapper&gt; mappers; private Connection conn; public MapperProxyFactory(Map&lt;String, Mapper&gt; mappers,Connection conn) { this.mappers = mappers; this.conn = conn; } /</em>*</li><li></li></ul><p>对当前正在执行的方法进行增强</p><p><code>*</code></p><p>取出当前执行的方法名称</p><p><code>*</code></p><p>取出当前执行的方法所在类</p><p><code>*</code></p><p>拼接成</p><ul><li>key</li><li><ul><li></li></ul></li></ul><p>去 <code>Map</code> 中获取 <code>Value</code>（</p><ul><li>Mapper)</li><li><ul><li></li></ul></li></ul><p>使用工具类 <code>Executor</code> 的 <code>selectList</code> 方法</p><p>*/ @Override public Object invoke(Object proxy, Method method, Object[] args) throws Throwable { //1. 取出方法名</p><p>String methodName = method.getName(); //2. 取出方法所在类名</p><p>String className = method.getDeclaringClass().getName(); //3. 拼接成</p><p>Key String key = className+&quot;.&quot;+methodName; //4. 使用 <code>key</code> 取出</p><p>mapper Mapper mapper = mappers.get(key); if(mapper == null) { throw new IllegalArgumentException(&quot; 传入的参数有误，无法获取执行的必要条件</p><p>&quot;); } //5. 创建 <code>Executor</code> 对象</p><p>Executor executor = new Executor(); ￼</p><p>} } <strong>运行测试类</strong></p><p>/** *</p><ul><li>&lt;p&gt;Title: MybatisTest&lt;/p&gt;</li><li>&lt;p&gt;Description: 测试 <code>mybatis</code> 的环境</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class MybatisTest { public static void main(String[] args)throws Exception { //1. 读取配置文件</li></ul><p>InputStream in = Resources.getResourceAsStream(&quot;SqlMapConfig.xml&quot;); //2. 创建 <code>SqlSessionFactory</code> 的构建者对象</p><p>SqlSessionFactoryBuilder builder = new SqlSessionFactoryBuilder(); //3. 使用构建者创建工厂对象</p><p>SqlSessionFactory SqlSessionFactory factory = builder.build(in); //4. 使用 <code>SqlSessionFactory</code> 生产 <code>SqlSession</code> 对象</p><p>SqlSession session = factory.openSession(); //5. 使用 <code>SqlSession</code> 创建 <code>dao</code> 接口的代理对象</p><p>IUserDao userDao = session.getMapper(IUserDao.class); //6. 使用代理对象执行查询所有方法</p><p>List&lt;User&gt; users = userDao.findAll(); for(User user : users) { System.out.println(user); } //7. 释放资源</p><p>session.close(); in.close(); } } <strong>基于注解方式定义</strong> <code>Mybatis</code> <strong>框架</strong><strong>自定义</strong><code>@Select</code> <strong>注解</strong></p><p>/***</p><ul><li>&lt;p&gt;Title: Select&lt;/p&gt;</li><li>&lt;p&gt;Description: 自定义查询注解</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) public @interface Select { String value(); } <strong>修改持久层接口</strong></li></ul><p>/** *</p><ul><li>&lt;p&gt;Title: IUserDao&lt;/p&gt;</li><li>&lt;p&gt;Description: 用户的持久层操作</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public interface IUserDao { /</em>*</li><li></li></ul><p>查询所有用户</p><ul><li>@return */ @Select(&quot;select * from user&quot;) List&lt;User&gt; findAll(); } <strong>修改</strong></li></ul><ul><li>SqlMapConfig.xml</li><li>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;</li><li>&lt;configuration&gt;</li><li>&lt;!--</li></ul><p>配置 <code>mybatis</code> 的环境</p><ul><li>--&gt;</li><li>&lt;environments default=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>配置 <code>mysql</code> 的环境</p><ul><li>--&gt;</li><li>&lt;environment id=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>配置事务的类型</p><p>--&gt; &lt;transactionManager type=&quot;JDBC&quot;&gt;&lt;/transactionManager&gt; &lt;!-- 配置连接数据库的信息：用的是数据源<code>(</code>连接池</p><ul><li>) --&gt;</li><li>&lt;dataSource type=&quot;POOLED&quot;&gt;</li></ul><p>￼</p><p>&lt;property name=&quot;url&quot; value=&quot;jdbc:mysql://localhost:3306/ee50&quot;/&gt; &lt;property name=&quot;username&quot; value=&quot;root&quot;/&gt; &lt;property name=&quot;password&quot; value=&quot;1234&quot;/&gt; &lt;/dataSource&gt; &lt;/environment&gt; &lt;/environments&gt; &lt;!-- 告知 <code>mybatis</code> 映射配置的位置</p><ul><li>--&gt;</li><li>&lt;mappers&gt;</li><li>&lt;mapper class=&quot;com.itheima.dao.IUserDao&quot;/&gt;</li><li>&lt;/mappers&gt;</li><li>&lt;/configuration&gt;</li></ul><p><strong>自定义</strong> <code>Mybatis</code> <strong>的设计模式说明</strong><strong>工厂模式（</strong><code>SqlSessionFactory</code><strong>）</strong> 工厂模式是我们最常用的实例化对象模式了，是用工厂方法代替new操作的一种模式。工厂模式可能多做一些工作，但会给你系统 带来更大的可扩展性和尽量少的修改量。</p><p>工厂模式的原理如下图：</p><p>代理模式(MapperProxyFactory) <strong>组成：</strong> 抽象角色：通过接口或抽象类声明真实角色实现的业务方法。 代理角色：实现抽象角色，是真实角色的代理，通过真实角色的业务逻辑方法来实现抽象方法，并可以附加自己的操作。 真实角色：实现抽象角色，定义真实角色所要实现的业务逻辑，供代理角色调用。 代理模式分为静态和动态代理。 静态代理，我们通常都很熟悉。有一个写好的代理类，实现与要代理的类的一个共同的接口，目的是为了约束也为了安全。具体不再多说。 这里主要想说的是关于动态代理。我们知道静态代理若想代理多个类，实现扩展功能，那么它必须具有多个代理类分别取代理不同的实现类。这样做的后果是造成太多的代码冗余。那么我们会思考如果做，才能既满足需求，又没有太多的冗余代码呢？——————动态代理。通过前面的课程我们已经学过了基于 <code>JDK</code> 的动态代理实现方式，今 天我们就会使用</p><p><code>JDK</code></p><p>动态代理方式来编写 <code>MapperProxyFactory</code> 类。 动态代理模型图：</p><p><strong>构建者模式</strong><code>(SqlSessionFactoryBuilder)</code> 其核心思想是将一个“复杂对象的构建算法”与它的“部件及组装方式”分离，使得构件算法和组装方式可以独立应对变化；利用同样的构建算法可以创建不同的表示，不同的构建过程可以利用相同的部件组装方式。</p><p>首先我们一起来学习构建者模式，通过百度百科如下： 具体设计模式的模型图如下：</p><p>从图中我们可以看出，创建者模式由四部分组成。 <strong>抽象创建者角色</strong>：给出一个抽象接口，以规范产品对象的各个组成成分的建造。一般而言，此接口独立于应用程序的商业逻辑。模式中直接创建产品对象的是具体创建者角色。具体创建者必须实现这个接口的两种方法：一是建造方法，比如图中的 <code>buildPart1</code> 和 <code>buildPart2</code> 方法；另一种是结果返回方法，即图中的 <code>getProduct</code> 方法。一般来说，产品所包含的零件数目与建造方法的数目相符。换言之，有多少零件，就有多少相应的建造方法。 **具体创建者角色：**他们在应用程序中负责创建产品的实例。这个角色要完成的任务包括：</p><p><code>1</code></p><p>、实现抽象创建者所声明的抽象方法，给出一步一步的完成产品创建实例的操作。</p><p><code>2</code></p><p>、在创建完成后，提供产品的实例。 **导演者角色：**这个类调用具体创建者角色以创建产品对象。但是导演者并没有产品类的具体知识，真正拥有产品类的具体知识的是具体创建者角色。 **产品角色：**产品便是建造中的复杂对象。一般说来，一个系统中会有多于一个的产品类，而且这些产品类并不一定有共同的接口，而完全可以使不相关联的。</p><p><strong>小结</strong> 通过自定义</p><p><code>Mybatis</code></p><p>框架的学习，我们将前面的基础知识很好的结合在一起，并且强化了我们的设计模式及 使用。希望大家能够抽时间多练习，这也是系统架构师的必由之路。</p></div>',1)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
